theme_fields.value:
@mixin pill($r) {
  border-radius: $r;
  padding: 0.5em 1em;
}
.styled-button {
  @include pill(999px);
  background: lighten($tertiary, 10%);
  color: darken($tertiary, 20%);
  &:hover { background: mix($primary, $secondary, 30%); }
}

@import "buttons";
.styled {
  color: $accent;
  border: if($show_border == "true", #{$width}px solid rgba($primary, 0.25), none);
  background-image: url($hero);
  width: calc(100% - #{$width * 2}px);
  transform: scale($ratio);
  &::after { content: $label; }
  .nested > a { text-decoration: underline dotted; user-select: none; }
  @media (max-width: 600px) { display: none; }
}
.choice-#{$choice} { opacity: 0.5; margin: -0.5em; }
.items { content: "#{$items}"; }
.boxed { -webkit-box-shadow: 0 0 1px red; box-shadow: 0 0 1px red; backdrop-filter: blur(2px); }
@-webkit-keyframes styled-spin { from { opacity: 0; } }
@keyframes styled-spin { from { opacity: 0; } to { opacity: 1; } }
:root {
  --styled-bg: light-dark(#{$secondary}, #{$primary});
  --styled-fg: #{scale-color($tertiary, $lightness: -25%)};
}
.dark { color-scheme: dark; }
@supports (display: grid) { .grid { display: grid; } }
